/* The declination in degrees, east positive, at `latitude` / `longitude` (degrees), `height` km above the
 * ellipsoid, in `year` (decimal). Not at the poles themselves (within 0.1 degree of them: NAN). */
static double
wmm_declination(double latitude, double longitude, double height, double year)
{
	const double a = 6378.137, flattening = 1 / 298.257223563, e2 = flattening * (2 - flattening), re = 6371.2;
	double phi = latitude * M_PI / 180, lambda = longitude * M_PI / 180, dt = year - WMM_EPOCH;
	double rc = a / sqrt(1 - e2 * sin(phi) * sin(phi));
	double xp = (rc + height) * cos(phi), zp = (rc * (1 - e2) + height) * sin(phi);
	double r = sqrt(xp * xp + zp * zp), phic = asin(zp / r);
	double ct = sin(phic), st = cos(phic);          /* cos and sin of the geocentric colatitude */
	double p[WMM_DEGREE + 1][WMM_DEGREE + 1] = { { 0 } }, dp[WMM_DEGREE + 1][WMM_DEGREE + 1] = { { 0 } };
	double br = 0, bt = 0, bp = 0, x, y, z, psi;

	if (fabs(latitude) > 89.9) {
		return NAN;
	}
	p[0][0] = 1;
	for (int n = 1; n <= WMM_DEGREE; n++) {
		for (int m = 0; m <= n; m++) {
			if (m == n) {
				double k = n == 1 ? 1 : sqrt((2.0 * n - 1) / (2.0 * n));

				p[n][n] = k * st * p[n - 1][n - 1];
				dp[n][n] = k * (st * dp[n - 1][n - 1] + ct * p[n - 1][n - 1]);
			} else {
				double k = sqrt((double)n * n - (double)m * m);
				double k2 = m <= n - 2 ? sqrt((double)(n - 1) * (n - 1) - (double)m * m) : 0;

				p[n][m] = ((2.0 * n - 1) * ct * p[n - 1][m] - (m <= n - 2 ? k2 * p[n - 2][m] : 0)) / k;
				dp[n][m] = ((2.0 * n - 1) * (ct * dp[n - 1][m] - st * p[n - 1][m]) -
				    (m <= n - 2 ? k2 * dp[n - 2][m] : 0)) / k;
			}
		}
	}
	for (unsigned i = 0; i < sizeof(wmm_coefficients) / sizeof(wmm_coefficients[0]); i++) {
		int n = wmm_coefficients[i].n, m = wmm_coefficients[i].m;
		double g = wmm_coefficients[i].g + dt * wmm_coefficients[i].g_rate;
		double h = wmm_coefficients[i].h + dt * wmm_coefficients[i].h_rate;
		double ar = pow(re / r, n + 2), cm = cos(m * lambda), sm = sin(m * lambda);

		br += (n + 1) * ar * (g * cm + h * sm) * p[n][m];
		bt -= ar * (g * cm + h * sm) * dp[n][m];
		bp += ar * m * (g * sm - h * cm) * p[n][m];
	}
	bp /= st;
	/* north, east, down at the geocentric position; then turned to the geodetic vertical */
	x = -bt;
	y = bp;
	z = -br;
	psi = phic - phi;
	x = x * cos(psi) - z * sin(psi);
	return atan2(y, x) * 180 / M_PI;
}
